SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'entscheidungen', 'Entscheidungsdokumentation (tabellarisch, § 5.3.2)', 'json', NULL, false, '§ 5.3.1; § 5.3.2', 'Plan 3: Zeilen je Entscheidung; Ausgaben decisions_count / decisions_ohne_begruendung (820-2-12-D1 / D2) neben dem Boolean decisions_documented (gelesen von REQ-25, konsumiert von -15 / -21) — Umstellung von REQ-25 STAGED (m820_2-G-11).', 'imported_unverified', 'Eine tabellarische Entscheidungsdokumentation wird geführt. — Die Dokumentation von in der Besprechung getroffenen Entscheidungen enthält eine Begründung, um Entscheidungsprozesse im weiteren Projektverlauf nachvollziehbar zu machen. — Bei der Dokumentation von Entscheidungen werden auch die Gründe, die dazu geführt haben, dokumentiert.', 'register', '{"title":"Entscheidungsdokumentation (tabellarisch)","subtitle":"§ 5.3.1 / § 5.3.2 — je Entscheidung eine Zeile: Nr., Datum, Entscheidung, Begründung, Entscheider","add_label":"+ Entscheidung","placement":"section","columns":[{"key":"nr","label":"Nr.","type":"number","required":true,"min":1,"width":"w-20","aria_label":"laufende Nummer der Entscheidung"},{"key":"datum","label":"Datum","type":"date","required":true},{"key":"entscheidung","label":"Entscheidung","type":"text","required":true},{"key":"begruendung","label":"Begründung","type":"text"},{"key":"entscheider","label":"Entscheider","type":"text"}],"footer":["decisions_count","decisions_ohne_begruendung"],"note":"Eine tabellarische Entscheidungsdokumentation wird geführt. Bei größeren, langlaufenden Projekten oder dem Wechsel beim verantwortlichen Personal geht bei einer alleinigen Dokumentation in den Protokollen schnell die Übersicht verloren. Entscheidungen müssen, einschließlich der Gründe, transparent und nachvollziehbar dokumentiert sein und dauerhaft Bestand haben. Dies führt zu einem stabilen Planungsprozess. Bei der Dokumentation von Entscheidungen werden auch die Gründe, die dazu geführt haben, dokumentiert."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'entscheidungen') AND w.code = '820-2-12' AND s.code = 'DWA-M-820-2';
