SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'dritte', 'Beteiligte Dritte (§ 5.3.5)', 'json', NULL, false, '§ 5.3.5', 'Plan 3: Zeilen je beauftragter / geplanter Drittleistung; Ausgabe third_parties_count (820-2-13-D1) neben dem Boolean third_parties_engaged_early (gelesen von REQ-28, konsumiert von -14 / -15) — ein Zusatz-Gate ist STAGED (m820_2-G-12).', 'imported_unverified', 'Der Bedarf an Fachplanungen, Gutachten, Rechtsberatung etc. ist intensiv zu recherchieren und realistisch zu ermitteln. Beteiligte Dritte sind möglichst frühzeitig in das Projekt einzubinden und, falls erforderlich, frühzeitig zu beauftragen. Die Anforderungen der Beteiligten sind aktiv einzufordern und in die Planung zu integrieren. — Im Rahmen der Projektvorbereitung wird eine umfassende Liste der Projektbeteiligten (Zuarbeit beispielsweise durch die Bedarfsplanung und die Objektplaner in LPH 1 „Grundlagenermittlung“) erstellt, erforderliche Leistungen werden möglichst früh beauftragt.', 'register', '{"title":"Beteiligte Dritte (Fachplanungen, Gutachten, Rechtsberatung)","subtitle":"§ 5.3.5 — je Leistung eine Zeile: Leistung, Büro, Beauftragung","add_label":"+ Dritter","placement":"section","columns":[{"key":"leistung","label":"Leistung (Fachplanung / Gutachten / Beratung)","type":"text","required":true,"datalist":["Fachplanung","Gutachten","Rechtsberatung"]},{"key":"buero","label":"Büro / Dritter","type":"text"},{"key":"beauftragt","label":"Beauftragt am","type":"date"}],"footer":["third_parties_count"],"note":"Der Bedarf an Fachplanungen, Gutachten, Rechtsberatung etc. ist intensiv zu recherchieren und realistisch zu ermitteln. Beteiligte Dritte sind möglichst frühzeitig in das Projekt einzubinden und, falls erforderlich, frühzeitig zu beauftragen. Die Anforderungen der Beteiligten sind aktiv einzufordern und in die Planung zu integrieren. Im Rahmen der Projektvorbereitung wird eine umfassende Liste der Projektbeteiligten (Zuarbeit beispielsweise durch die Bedarfsplanung und die Objektplaner in LPH 1 „Grundlagenermittlung“) erstellt, erforderliche Leistungen werden möglichst früh beauftragt."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
