SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'vergaben_los', 'Vergaben je Los / Gewerk', 'json', NULL, false, '§ 5.3.8; § 5.5; § 5.7.3', 'Plan 3: Zeilen je Los; Ausgaben lots_count / final_contract_value_calc (820-2-19-D1 / D2) als Zwillinge zu den Einzelwerten final_contract_value, vergabeverfahren_used, zuschlag_erteilt_datum (m820_2-D-1 … D-3) und zum Boolean lot_strategy_documented auf -13 (REQ-31 — m820_2-G-14); speist die Loseausnahme des Teils 1 erst nach einer Phase-6-Anbindung (m820_2-X-1).', 'imported_unverified', 'Gewerke und Lose bei Planungs- und Bauleistungen dürfen in der Regel nur aus technischen Gründen zusammengefasst werden. Besteht die Verpflichtung zur losweisen Vergabe, resultiert daraus Koordinationsaufwand beim Auftraggeber. — Die für den Projekterfolg erforderliche Aufteilung von Losen und Gewerken wird nach technischen Erfordernissen intensiv durchdacht und transparent begründet. — Der Auftraggeber ist sich nicht immer darüber im Klaren, dass er die Bauleistungen abnehmen muss und bei Losen und Gewerken zu unterschiedlichen Zeitpunkten.', 'register', '{"title":"Vergaben je Los / Gewerk","subtitle":"§ 5.3.8 / § 5.5 / § 5.7.3 — je Los eine Zeile: Los / Gewerk, Verfahren, Zuschlagsdatum, Auftragswert","add_label":"+ Los / Gewerk","placement":"section","columns":[{"key":"los","label":"Los / Gewerk","type":"text","required":true},{"key":"verfahren","label":"Vergabeverfahren","type":"text"},{"key":"zuschlag","label":"Zuschlag erteilt am","type":"date"},{"key":"auftragswert","label":"Auftragswert","type":"number","unit":"EUR","required":true,"min":0,"aria_label":"Auftragswert des Loses in Euro"}],"footer":["lots_count","final_contract_value_calc"],"note":"Gewerke und Lose bei Planungs- und Bauleistungen dürfen in der Regel nur aus technischen Gründen zusammengefasst werden. Besteht die Verpflichtung zur losweisen Vergabe, resultiert daraus Koordinationsaufwand beim Auftraggeber. Die für den Projekterfolg erforderliche Aufteilung von Losen und Gewerken wird nach technischen Erfordernissen intensiv durchdacht und transparent begründet. Der Auftraggeber ist sich nicht immer darüber im Klaren, dass er die Bauleistungen abnehmen muss und bei Losen und Gewerken zu unterschiedlichen Zeitpunkten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'vergaben_los') AND w.code = '820-2-19' AND s.code = 'DWA-M-820-2';
