UPDATE fields f SET widget = 'register', ui_config = '{"title":"Bauänderungen / Nachträge","subtitle":"§ 4.3.7 · § 5.6.4 — je Änderung eine Zeile; Anzahl, Volumen und offene Änderungen abgeleitet","add_label":"+ Bauänderung / Nachtrag","placement":"bottom","columns":[{"key":"aenderung","label":"Bauänderung / Nachtrag","type":"text","required":true},{"key":"datum","label":"Datum","type":"date","width":"w-40"},{"key":"kosten_eur","label":"Kostenwirkung (€)","type":"number","unit":"EUR","width":"w-32","aria_label":"Kostenwirkung der Änderung in Euro"},{"key":"terminwirkung","label":"Terminwirkung","type":"text"},{"key":"entscheidung","label":"Entscheidung / Begründung","type":"text"},{"key":"status","label":"Status","type":"enum","required":true,"options":["offen","genehmigt","abgelehnt","umgesetzt"]}],"footer":["change_orders_count","change_orders_sum","change_orders_open"],"note":"Auf der Grundlage klarer und transparent definierter Projektziele werden Änderungen, verursacht durch Auftraggeber (Bauherren, Betreiber) oder Auftragnehmer, nach einem klar festgelegten Ablauf, beispielweise mithilfe von Formblättern, bearbeitet. Die Auswirkungen auf die Projektziele (beispielsweise Kosten, Termine, Qualitäten und Quantitäten) sind dargestellt. Der Auslöser bzw. Verursacher für die Projektänderung und die Kostenübernahmen werden geklärt und müssen in Textform dokumentiert werden. Auswirkungen auf die Projektziele (Termine, Kosten, Qualitäten, inklusive Planungskosten) sind geklärt und beschrieben. Konsequenzen auf den weiteren Projektverlauf sind bekannt. Projektänderungen werden zügig und zum Projektablauf passend vom Auftraggeber in Textform genehmigt und freigegeben. Werden Änderungen aus besonderen Gründen erforderlich, ist das Änderungsmanagement konsequent zu führen. Eine Änderung ohne Kostenwirkung zählt mit 0 € (Kostenwirkung darf leer bleiben)."}'::jsonb, lookup = NULL, visible_when = NULL FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'change_orders' AND w.code = '820-2-21' AND s.code = 'DWA-M-820-2' AND f.active;
