FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'change_orders_count') AND w.code = '820-2-21' AND s.code = 'DWA-M-820-2';
