SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'gewaehrleistungen', 'Gewährleistungskalender (§ 5.8.2)', 'json', NULL, false, '§ 5.8.2; § 5.8.3', 'Plan 3: Zeilen je Auftragnehmer / ausführender Firma (Abnahme, Beginn, Ende, offene Mängel); Ausgaben warranty_count / warranty_open_defects (820-2-24-D1 / D2); frühester Beginn / spätestes Ende sind m820_2-F-1 (keine Datumsfunktionen); REQ-51 liest weiterhin das Einzeldatumspaar — Umstellung STAGED (m820_2-G-15, D-4 / D-5).', 'imported_unverified', 'Es gibt einen eindeutigen Abnahmezeitpunkt für jeden Auftragnehmer. — Für jeden Auftragnehmer und für jede ausführende Firma wird eine Abnahme durchgeführt. — Die Abnahmen werden mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfrist dokumentiert. — Es wird ein Gewährleistungskalender, mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfristen, für jeden Auftragnehmer und für jede ausführende Firma geführt.', 'register', '{"title":"Gewährleistungskalender","subtitle":"§ 5.8.2 — je Auftragnehmer und je ausführender Firma eine Zeile: Abnahme, Beginn und Ende der Gewährleistungsfrist, offene Mängel","add_label":"+ Auftragnehmer / Firma","placement":"section","columns":[{"key":"auftragnehmer","label":"Auftragnehmer / ausführende Firma","type":"text","required":true},{"key":"abnahme","label":"Abnahme am","type":"date","required":true},{"key":"beginn","label":"Beginn der Gewährleistungsfrist","type":"date","required":true},{"key":"ende","label":"Ende der Gewährleistungsfrist","type":"date","required":true},{"key":"maengel_offen","label":"Offene Mängel","type":"number","min":0,"width":"w-24","aria_label":"Anzahl offener Mängel dieses Auftragnehmers"}],"footer":["warranty_count","warranty_open_defects"],"note":"Für jeden Auftragnehmer und für jede ausführende Firma wird eine Abnahme durchgeführt. Die Abnahmen werden mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfrist dokumentiert. Es wird ein Gewährleistungskalender, mit Angabe des Beginns und des Endes der jeweiligen Gewährleistungsfristen, für jeden Auftragnehmer und für jede ausführende Firma geführt. Frühester Beginn / spätestes Ende werden nicht berechnet (die Ausdruckssprache hat keine Datumsfunktionen — m820_2-F-1); die Einzelfelder warranty_start_date / warranty_end_date bleiben (m820_2-D-4 / D-5)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'gewaehrleistungen') AND w.code = '820-2-24' AND s.code = 'DWA-M-820-2';
