SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'bim_methode_angewendet', 'Das Projekt wird mit der BIM-Methode abgewickelt (Eignung und Kompetenzen geklärt)', 'boolean', NULL, false, '§ 8.3.2', 'Plan 3: Treiber für REQ-59 ("BIM basics established (if applicable)", heute leere Bedingung auf 820-2-25) — Vorschlag IF bim_methode_angewendet == true THEN bim_basics_established == true auf -27 STAGED (m820_2-G-5); die übrigen Felder von -27 / -28 sind nicht BIM-bedingt (m820_2-J-3).', 'imported_unverified', 'Es ist geprüft, ob die BIM-Methode beim Auftraggeber angewendet werden kann, ob das Know-how und die Ressourcen zur Verfügung stehen. — Es wird geklärt, ob das Projekt für die Anwendung der BIM-Methodik geeignet ist und ob die Beteiligten sowohl beim Auftraggeber als auch bei den Auftragnehmern die nötigen Kompetenzen und Qualifikationen aufweisen.', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bim_methode_angewendet') AND w.code = '820-2-27' AND s.code = 'DWA-M-820-2';
COMMIT;
